514	            body.set(new SettingInput(key, perm(request.value()), null, request.user()));
515	            return;
516	        }
517	        if (!SettingStore.CLERK_LIMIT.equals(key) && !cap && !proof && !note && !floor && !terms && !gradeTerms && !gradeGrace && !late && !dated) {
518	            throw new InvalidSheetException("Not a setting: " + key);
519	        }
520	        String value = request.value() == null ? "" : request.value().trim();
521	        String fromValue = request.from() == null ? "" : request.from().trim();
522	        LocalDate from = null;
523	        if (!dated && !fromValue.isEmpty()) {
524	            try {
525	                from = LocalDate.parse(fromValue);
526	            } catch (DateTimeParseException e) {
527	                throw new InvalidSheetException("The from-date must be a date (YYYY-MM-DD), or blank");
528	            }
529	        }
530	        if (dated) {
531	            if (value.isEmpty()) {
532	                body.set(new SettingInput(key, null, from, request.user()));
533	                return;
534	            }
535	            try {
536	                body.set(new SettingInput(key, LocalDate.parse(value).toString(), from, request.user()));
537	            } catch (DateTimeParseException e) {
