541	            return;
542	        }
543	        if (gradeGrace) {
544	            if (value.isEmpty()) {
545	                body.set(new SettingInput(key, null, from, request.user()));
546	                return;
547	            }
548	            if (!DAYS.matcher(value).matches()) {
