557	                return;
558	            }
559	            if (!DAYS.matcher(value).matches()) {
560	                throw new InvalidSheetException("The grade's terms must be a whole number of days, 0 or more, or blank");
561	            }
562	            body.set(new SettingInput(key, String.valueOf(Integer.parseInt(value)), from, request.user()));
563	            return;
564	        }
565	        if (terms) {
