581	            body.set(new SettingInput(key, SettingStore.DEFAULT_LATE_PCT.toPlainString(), from, request.user()));
582	            return;
583	        }
584	        if (value.isEmpty()) {
585	            body.set(new SettingInput(key, null, from, request.user()));
586	            return;
587	        }
588	        if (!LIMIT.matcher(value).matches()) {
589	            throw new InvalidSheetException(floor ? "The floor must be 0.00 or more with up to two decimals"
590	                    : late ? "The late percent must be 0.00 or more with up to two decimals"
591	                    : proof ? "The proof threshold must be 0.00 or more with up to two decimals, or blank"
592	                    : note ? "The note threshold must be 0.00 or more with up to two decimals, or blank"
593	                    : cap ? "The cap must be 0.00 or more with up to two decimals, or blank"
594	                    : "The clerk limit must be 0.00 or more with up to two decimals, or blank");
595	        }
596	        body.set(new SettingInput(key, new BigDecimal(value).setScale(2).toPlainString(), from, request.user()));
597	    }
