package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateSetting {
    /** 0.00 or more, with up to two decimals. */
    private static final Pattern LIMIT = Pattern.compile("\\d+(\\.\\d{1,2})?");
    /** A whole number of days, 0 or more. */
    private static final Pattern DAYS = Pattern.compile("\\d{1,5}");

    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody SettingRequest request, Out<SettingInput> body, RoleStore roles) throws InvalidSheetException {
        roles.refuseChange(sheetId.trim(), request == null ? null : request.user());
        String key = request == null || request.key() == null ? "" : request.key().trim();
        boolean floor = SettingStore.FLOOR.equals(key);
        boolean terms = SettingStore.TERMS.equals(key);
        boolean gradeTerms = key.startsWith(SettingStore.TERMS_PREFIX)
                && SettingStore.GRADES.contains(key.substring(SettingStore.TERMS_PREFIX.length()));
        boolean gradeGrace = SettingStore.isGradeGrace(key);
        boolean late = SettingStore.LATE_PCT.equals(key);
        boolean numbering = SettingStore.PERIOD_NUMBERING_FROM.equals(key);
        boolean entry = SettingStore.ENTRY_DATE.equals(key);
        boolean dated = SettingStore.POLICY_DATE.equals(key) || numbering || entry;
        boolean cap = SettingStore.CAP.equals(key);
        boolean proof = SettingStore.PROOF_THRESHOLD.equals(key);
        boolean note = SettingStore.NOTE_THRESHOLD.equals(key);
        if (SettingStore.GRACE_DAYS.equals(key)) {
            String value = request.value() == null ? "" : request.value().trim();
            if (!value.isEmpty() && !DAYS.matcher(value).matches()) {
                throw new InvalidSheetException("The grace days must be a whole number of days, 0 or more, or blank");
            }
            body.set(new SettingInput(key, value.isEmpty() ? null : String.valueOf(Integer.parseInt(value)), null,
                    request.user()));
            return;
        }
        if (key.startsWith(SettingStore.PERM_PREFIX)
                && SettingStore.PERM_ACTIONS.contains(key.substring(SettingStore.PERM_PREFIX.length()))) {
            body.set(new SettingInput(key, perm(request.value()), null, request.user()));
            return;
        }
        if (!SettingStore.CLERK_LIMIT.equals(key) && !cap && !proof && !note && !floor && !terms && !gradeTerms && !gradeGrace && !late && !dated) {
            throw new InvalidSheetException("Not a setting: " + key);
        }
        String value = request.value() == null ? "" : request.value().trim();
        String fromValue = request.from() == null ? "" : request.from().trim();
        LocalDate from = null;
        if (!dated && !fromValue.isEmpty()) {
            try {
                from = LocalDate.parse(fromValue);
            } catch (DateTimeParseException e) {
                throw new InvalidSheetException("The from-date must be a date (YYYY-MM-DD), or blank");
            }
        }
        if (dated) {
            if (value.isEmpty()) {
                body.set(new SettingInput(key, null, from, request.user()));
                return;
            }
            try {
                body.set(new SettingInput(key, LocalDate.parse(value).toString(), from, request.user()));
            } catch (DateTimeParseException e) {
                throw new InvalidSheetException((numbering ? "The period numbering from" : entry ? "The entry date" : "The policy date")
                        + " must be a date (YYYY-MM-DD), or blank");
            }
            return;
        }
        if (gradeGrace) {
            if (value.isEmpty()) {
                body.set(new SettingInput(key, null, from, request.user()));
                return;
            }
            if (!DAYS.matcher(value).matches()) {
                throw new InvalidSheetException("The grade's grace days must be a whole number of days, 0 or more, or blank");
            }
            body.set(new SettingInput(key, String.valueOf(Integer.parseInt(value)), from, request.user()));
            return;
        }
        if (gradeTerms) {
            if (value.isEmpty()) {
                body.set(new SettingInput(key, null, from, request.user()));
                return;
            }
            if (!DAYS.matcher(value).matches()) {
                throw new InvalidSheetException("The grade's terms must be a whole number of days, 0 or more, or blank");
            }
            body.set(new SettingInput(key, String.valueOf(Integer.parseInt(value)), from, request.user()));
            return;
        }
        if (terms) {
            if (value.isEmpty()) {
                body.set(new SettingInput(key, String.valueOf(SettingStore.DEFAULT_TERMS), from, request.user()));
                return;
            }
            if (!DAYS.matcher(value).matches()) {
                throw new InvalidSheetException("The terms must be a whole number of days, 0 or more");
            }
            body.set(new SettingInput(key, String.valueOf(Integer.parseInt(value)), from, request.user()));
            return;
        }
        if (value.isEmpty() && floor) {
            body.set(new SettingInput(key, SettingStore.DEFAULT_FLOOR.toPlainString(), from, request.user()));
            return;
        }
        if (value.isEmpty() && late) {
            body.set(new SettingInput(key, SettingStore.DEFAULT_LATE_PCT.toPlainString(), from, request.user()));
            return;
        }
        if (value.isEmpty()) {
            body.set(new SettingInput(key, null, from, request.user()));
            return;
        }
        if (!LIMIT.matcher(value).matches()) {
            throw new InvalidSheetException(floor ? "The floor must be 0.00 or more with up to two decimals"
                    : late ? "The late percent must be 0.00 or more with up to two decimals"
                    : proof ? "The proof threshold must be 0.00 or more with up to two decimals, or blank"
                    : note ? "The note threshold must be 0.00 or more with up to two decimals, or blank"
                    : cap ? "The cap must be 0.00 or more with up to two decimals, or blank"
                    : "The clerk limit must be 0.00 or more with up to two decimals, or blank");
        }
        body.set(new SettingInput(key, new BigDecimal(value).setScale(2).toPlainString(), from, request.user()));
    }

    /** The roles listed, comma separated without spaces, or null when blank (the standing rule). */
    private static String perm(String raw) throws InvalidSheetException {
        String value = raw == null ? "" : raw.trim();
        if (value.isEmpty()) {
            return null;
        }
        List<String> roles = new ArrayList<>();
        for (String part : value.split(",")) {
            String role = part.trim();
            if (Role.of(role) == null || Role.of(role) == Role.VIEWER) {
                throw new InvalidSheetException("A permission lists roles (clerk, steward), comma separated, or is blank");
            }
            if (!roles.contains(role)) {
                roles.add(role);
            }
        }
        return String.join(",", roles);
    }
}
# GET /api/sheets/{sheetId}/settings — the sheet's settings in force on its today: clerk-limit (two
# decimals, null for no limit) and floor (two decimals, 1.00 until set), and so on; and the floor and
# late percent recorded by from-date (floorFrom, latePctFrom).
respond:
  class: net.officefloor.hq.app.setting.RespondWithSettings
  govern: [ readonly-transaction ]
# POST /api/sheets/{sheetId}/settings — change a setting (body: {key, value, from, user}). The keys are
# clerk-limit: a number of 0.00 or more with up to two decimals, or blank for no limit; and floor: the
# least a claim's live due may be, 0.00 or more with up to two decimals, blank for its default 1.00; and
# terms: the whole days (0 or more) after its date a claim is due by, blank for its default 14; and
# terms-A, terms-B, terms-C: a grade's own terms, which a claim of a person of that grade (on the claim's
# date) takes instead, blank to use the sheet's terms (a claim's due-by is fixed when it is added); and
# late-pct: the percent of an overdue claim's figure charged per full 30 days overdue, 0.00 or more with
# up to two decimals, blank for its default 0.00; and cap: the most a person's due-total may be, 0.00 or
# more with up to two decimals, or blank for none; note-threshold: the due above which a claim needs a
# note before it is opened, 0.00 or more with up to two decimals, or blank for none; and proof-threshold: the due above which a claim needs a
# proof before it is settled or approved, 0.00 or more with up to two decimals, or blank for none.
# Each of these is dated: its value is recorded from the from-date (yyyy-MM-dd, blank for the sheet's
# today), keeping the values recorded from other dates and replacing one recorded from the same date. A
# claim's floor, late percent, terms and proof threshold are those in force on its date; the clerk limit and cap those in
# force on the sheet's today. policy-date, period-numbering-from and entry-date are not dated (from is ignored);
# entry-date (yyyy-MM-dd, blank for off) is the default date of a new claim in place of the sheet's today.
# Any other key or value is refused (400) and nothing is stored. A stored change is recorded in the
# audit file as SETTING_CHANGED, ending from=<date> when a from-date was given (even when the value is the one already in force), then ROLLUP/TOTALS
# for the figures it moved; a refused one records nothing.
validate:
  class: net.officefloor.hq.app.setting.ValidateSetting
  next: snapshot
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.setting.SaveSetting
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.setting.AuditSettingChanged
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.setting.RespondWithSettings
  govern: [ transaction ]

